import sys

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    L = int(data[idx]); idx += 1
    C = int(data[idx]); idx += 1
    P = int(data[idx]); idx += 1
    blacks = set()
    for _ in range(P):
        x = int(data[idx]); idx += 1
        y = int(data[idx]); idx += 1
        blacks.add((x - 1, y - 1))

    # A cell can hold a white piece iff it's not black and has a black 4-neighbor
    valid = [[False] * C for _ in range(L)]
    for r in range(L):
        for c in range(C):
            if (r, c) in blacks:
                continue
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < L and 0 <= nc < C and (nr, nc) in blacks:
                    valid[r][c] = True
                    break

    # For each row, enumerate masks (bit = white piece) with:
    #  - whites only on valid cells
    #  - no two horizontally adjacent whites inside the row
    row_masks = []
    for r in range(L):
        masks = []
        for m in range(1 << C):
            if m & (m << 1):
                continue
            ok = True
            cnt = 0
            mm = m
            while mm:
                low = mm & (-mm)
                c = low.bit_length() - 1
                if not valid[r][c]:
                    ok = False
                    break
                cnt += 1
                mm ^= low
            if ok:
                masks.append((m, cnt))
        row_masks.append(masks)

    # DP over rows: state = mask of whites in current row.
    # Vertical adjacency check between consecutive rows: m & pm == 0.
    # (Only 4-directional adjacency matters; diagonals are allowed.)
    dp = {0: 0}
    for r in range(L):
        ndp = {}
        for pm, pc in dp.items():
            for m, cnt in row_masks[r]:
                if m & pm:
                    continue
                val = pc + cnt
                if ndp.get(m, -1) < val:
                    ndp[m] = val
        dp = ndp

    print(max(dp.values()))

main()
